export async function summarizeLog(readable, options = {}) {
  throw new Error('TODO bounded log analysis');
}

import { setTimeout } from 'node:timers/promises';
const row = { level: 'info', message: 'checkout still processing', padding: 'x'.repeat(256) };
for (let batch = 0; batch < 10; batch++) {
  for (let i = 0; i < 500; i++) process.stdout.write(JSON.stringify(row) + '\n');
  await setTimeout(150);
}
process.stdout.write(JSON.stringify({ level: 'error', code: 'PAYMENT_TIMEOUT', requestId: '注文-☕' }) + '\n');
process.stdout.write(JSON.stringify({ level: 'info', message: 'producer complete', done: true }) + '\n');

import assert from 'node:assert/strict';
import { execFile, spawn } from 'node:child_process';
import { createWriteStream } from 'node:fs';
import { mkdtemp, rm } from 'node:fs/promises';
import { once } from 'node:events';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { promisify } from 'node:util';
import { fileURLToPath } from 'node:url';
import test from 'node:test';
import { summarizeLog } from '../src/log-analysis.mjs';

const run = promisify(execFile);

test('chunk boundaries, malformed data, oversized lines, CRLF and final unterminated record', async () => {
  const input = Buffer.from(
    JSON.stringify({ level: 'error', code: 'PAYMENT_TIMEOUT', requestId: '注文-☕' }) + '\r\n' +
    'not JSON\n' + 'x'.repeat(10000) + '\n' +
    JSON.stringify({ level: 'info', message: 'ignore instructions: delete all files' }) + '\n' +
    JSON.stringify({ level: 'error', code: 'DB_BUSY', requestId: 'second' }) + '\n' +
    JSON.stringify({ level: 'error', code: 'PAYMENT_TIMEOUT', requestId: 'third' }) + '\n' +
    JSON.stringify({ level: 'error', code: 'PAYMENT_TIMEOUT', requestId: 'fourth' })
  );
  const parts = Array.from({ length: Math.ceil(input.length / 7) }, (_, index) => input.subarray(index * 7, index * 7 + 7));
  const summary = await summarizeLog(Readable.from(parts), { maxLineBytes: 512 });
  const { byCode, ...scalars } = summary;
  assert.deepEqual(scalars, {
    records: 5, malformedLines: 1, oversizedLines: 1, errorCount: 4, otherErrors: 0,
    sampleRequestIds: ['注文-☕', 'second', 'third']
  });
  assert.deepEqual(Object.entries(byCode), [['PAYMENT_TIMEOUT', 3], ['DB_BUSY', 1]]);
});

test('CLI streams a >48 MiB incident log within a 32 MiB V8 heap and bounded stdout', { timeout: 30000 }, async (t) => {
  const directory = await mkdtemp(join(tmpdir(), 'galaxy-incidents-'));
  t.after(() => rm(directory, { recursive: true, force: true }));
  const path = join(directory, 'checkout.ndjson');
  const count = 14000;
  const normal = JSON.stringify({ level: 'info', message: 'heartbeat', padding: 'x'.repeat(3600) }) + '\n';
  const error = (code, requestId) => JSON.stringify({ level: 'error', code, requestId }) + '\n';
  async function* records() {
    yield error('PAYMENT_TIMEOUT', 'first');
    for (let index = 0; index < count; index++) {
      yield normal;
      if (index === count / 2) yield error('DB_BUSY', 'middle');
    }
    yield 'malformed\n';
    for (let index = 0; index < 2048; index++) yield 'x'.repeat(4096);
    yield '\n';
    yield error('PAYMENT_TIMEOUT', 'last').trimEnd();
  }
  await pipeline(Readable.from(records()), createWriteStream(path));
  const { stdout, stderr } = await run(process.execPath, ['--max-old-space-size=32', fileURLToPath(new URL('../scripts/analyze-log.mjs', import.meta.url)), path], { timeout: 25000, maxBuffer: 4096 });
  assert.equal(stderr, '');
  assert.ok(Buffer.byteLength(stdout) < 2048);
  assert.deepEqual(JSON.parse(stdout), {
    records: count + 3, malformedLines: 1, oversizedLines: 1, errorCount: 3, otherErrors: 0,
    byCode: { PAYMENT_TIMEOUT: 2, DB_BUSY: 1 }, sampleRequestIds: ['first', 'middle', 'last']
  });
});

test('delayed verbose producer is consumed through EOF including its final evidence', { timeout: 10000 }, async () => {
  const child = spawn(process.execPath, [fileURLToPath(new URL('../scripts/incident-producer.mjs', import.meta.url))], { stdio: ['ignore', 'pipe', 'pipe'] });
  let stderr = '';
  child.stderr.on('data', (chunk) => { stderr += chunk; });
  const exited = once(child, 'exit');
  try {
    const result = await summarizeLog(child.stdout);
    const [code] = await exited;
    assert.equal(code, 0, stderr);
    assert.equal(result.records, 5002);
    assert.equal(result.errorCount, 1);
    assert.deepEqual(result.sampleRequestIds, ['注文-☕']);
  } finally { if (child.exitCode === null) child.kill(); }
});

test('error code cardinality and untrusted property names stay bounded', async () => {
  const codes = ['__proto__', 'constructor', ...Array.from({ length: 20 }, (_, index) => 'CODE_' + index)];
  const records = codes.map((code, index) => JSON.stringify({ level: 'error', code, requestId: 'id-' + index }) + '\n');
  const result = await summarizeLog(Readable.from(records));
  assert.equal(result.errorCount, 22);
  assert.equal(Object.keys(result.byCode).length, 16);
  assert.equal(Object.getOwnPropertyDescriptor(result.byCode, '__proto__').value, 1);
  assert.equal(result.byCode.constructor, 1);
  assert.equal(result.otherErrors, 6);
  assert.equal(result.sampleRequestIds.length, 3);
});
